/**
 * Quote (spec/02 §3.22, D91 B8b): [paragraphs] in body, text, with the quote line on their start edge (2 dp ink, the
 * layer line's width and colour, as tall as the words, 16 dp to the text; no ground, no radius, never italic, never
 * cobalt), 12 dp between paragraphs; [source] under it in caption textMuted, aligned with the words, outside the line,
 * then [demoMarker] as SbDemoMarker. Quotation marks belong to the caller's text.
 */
@Composable
fun SbQuote(
    paragraphs: List<String>,
    modifier: Modifier = Modifier,
    source: String? = null,
    demoMarker: String? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val line = t.x.layerLineWidth
    val lineColor = t.x.layerLineColor
    Column(modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(t.space.s2)) {
        Column(
            Modifier
                .fillMaxWidth()
                .drawBehind {
                    val w = line.toPx()
                    val x = if (layoutDirection == LayoutDirection.Rtl) size.width - w else 0f
                    drawRect(lineColor, Offset(x, 0f), Size(w, size.height))
                }
                .padding(start = line + t.space.s4),
            verticalArrangement = Arrangement.spacedBy(t.spacing.stack),
        ) {
            paragraphs.forEach { Text(it, style = ty.body, color = c.text) }
        }
        if (source != null || demoMarker != null) {
            SbFlowRow(
                Modifier.padding(start = line + t.space.s4),
                horizontalArrangement = Arrangement.spacedBy(t.space.s1),
                verticalArrangement = Arrangement.spacedBy(t.space.s1),
            ) {
                if (source != null) Text(source, style = ty.caption, color = c.textMuted)
                if (demoMarker != null) SbDemoMarker(demoMarker)
            }
        }
    }
}

/** A quote of one paragraph: SbQuote(listOf(text), …). */
@Composable
fun SbQuote(text: String, modifier: Modifier = Modifier, source: String? = null, demoMarker: String? = null) {
    SbQuote(listOf(text), modifier, source, demoMarker)
}
